#include "WebServerManager.h"

#include "JointLimits.h"
#include "MessageSchema.h"
#include "WebAssets.h"  // generated by tools/embed_assets.py from data/

namespace Comms {

namespace {
// Look up an embedded asset by URL path. Returns nullptr if not found.
const WebAssets::Asset* findAsset(const String& uri) {
    for (size_t i = 0; i < WebAssets::kAssetCount; ++i) {
        if (uri == WebAssets::kAssets[i].path) {
            return &WebAssets::kAssets[i];
        }
    }
    return nullptr;
}
}  // namespace

WebServerManager::WebServerManager() : server_(80) {}

WebServerManager::~WebServerManager() = default;

void WebServerManager::begin() {
    // Web UI is compiled into the firmware (no filesystem needed).
    Serial.printf("WebServerManager: %u embedded assets\n",
                  (unsigned)WebAssets::kAssetCount);

    server_.on("/", HTTP_GET, [this]() { handleRoot(); });
    server_.on("/api/limits", HTTP_GET, [this]() { handleApiLimits(); });
    server_.on("/api/status", HTTP_GET, [this]() { handleApiStatus(); });
    server_.onNotFound([this]() { handleNotFound(); });
    server_.begin();
    Serial.println("WebServerManager: HTTP server started on port 80");
}

void WebServerManager::handleClient() {
    server_.handleClient();
}

void WebServerManager::setStatusPayload(const String& state) {
    state_ = state;
}

void WebServerManager::setLastError(const String& lastError) {
    lastError_ = lastError;
}

void WebServerManager::setLimitsPayload(const String& payloadProfile,
                                       float minReach,
                                       float maxReach) {
    payloadProfile_ = payloadProfile;
    minReach_ = minReach;
    maxReach_ = maxReach;
}

void WebServerManager::handleRoot() {
    const WebAssets::Asset* a = findAsset("/index.html");
    if (a) {
        server_.send_P(200, a->mime, reinterpret_cast<PGM_P>(a->data), a->size);
        return;
    }
    server_.send(503, "text/plain", "index.html was not embedded. Check data/ and rebuild.");
}

void WebServerManager::handleApiLimits() {
    const String payload = buildLimitsResponse(payloadProfile_.c_str(),
                                              minReach_,
                                              maxReach_,
                                              -170.0f,
                                              170.0f,
                                              JointLimits::kL1_cm,
                                              JointLimits::kL2_cm,
                                              JointLimits::kL3_cm,
                                              JointLimits::kD1_cm);
    server_.send(200, "application/json", payload);
}

void WebServerManager::handleApiStatus() {
    const String payload = buildStatusResponse(
        state_.c_str(), lastError_.isEmpty() ? nullptr : lastError_.c_str());
    server_.send(200, "application/json", payload);
}

void WebServerManager::handleNotFound() {
    const WebAssets::Asset* a = findAsset(server_.uri());
    if (a) {
        server_.send_P(200, a->mime, reinterpret_cast<PGM_P>(a->data), a->size);
        return;
    }
    server_.send(404, "text/plain", "Not found");
}

}  // namespace Comms
